  [9024] = { nil, nil, nil, "Posso aiutarti in qualcosa?", nil, nil, nil, nil, 0xdf112bb5, nil, "mmm.m" },
  [9065] = { "La missione \"Chow\" (123)aa", "Uccidi Kobold Vermin, 2 in tutto.", "$N1! Uccidi Kobold Vermin, 2 in tutto.", nil, nil, 0xdb0905c3, 0x314b469d, 0xb19a2ce2, nil, nil, "...mm" },
  [9085] = { nil, nil, nil, "Hai avuto fortuna, {name}?", nil, nil, nil, nil, 0x10763147, nil, "mmm.m" },
  [9124] = { "L'armatura Cryptstalker non si fa da sola...", "Il cacciatore Leopold, alla ⟦Light's Hope Chapel=Cappella della Luce⟧ nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 30 ⟦Crypt Fiend Parts=Parti di Ragno delle Cripte⟧.", "Che ne diresti di guadagnarti una di queste monete luccicanti?\n\n<Leopold solleva un'insegna della Crociata.>\n\nHo un piccolo problema in cui potresti aiutarmi, {name}. Vedi, io realizzo armature Cryptstalker per chi è abbastanza matto da avventurarsi a Naxxramas. Loro mi forniscono i materiali principali per l'armatura, ma io resto sempre senza parti di ragno delle cripte. Portami un fascio di parti e ti pagherò con un'insegna, utilizzabile presso il furiere.", "Come va la caccia?", "Ah, questo andrà benissimo, {name}. Ricorda, accetto sempre altre parti. Per ogni fascio che mi porti, ti ricompenserò con un'insegna.", 0xa2b385ba, 0x878a3fbf, 0x61c659aa, 0xe02b27bb, 0xe90182ae, "....." },
  [9260] = { "Indagare sul Flagello a ⟦Stormwind=Roccavento⟧", "Raccogli 3 Dim Necrotic Stone dal Flagello fuori ⟦Stormwind=Roccavento⟧ e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere ⟦Stormwind=Roccavento⟧ da questi maledetti invasori?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0x00e4dbef, 0x9dc15400, 0x584b0283, 0x5ea2db66, 0x4f3229e9, "....." },
  [9261] = { "Indagine sul Flagello a ⟦Ironforge=Forgiardente⟧", "Raccogli tre Dim Necrotic Stone dal Flagello fuori da ⟦Ironforge=Forgiardente⟧ e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere ⟦Ironforge=Forgiardente⟧ da questi invasori maledetti?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0x71257d44, 0x40d576b1, 0x6d9b70a9, 0x5ea2db66, 0x4f3229e9, "....." },
